class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        INF = float('inf')

        dp = {}
        for a in range(3):
            for b in range(3):
                if a != b:
                    dp[(a, b)] = cost[0][a] + cost[n-1][b]

        for i in range(1, n // 2):
            left, right = i, n - 1 - i
            new_dp = {}
            for a in range(3):
                for b in range(3):
                    if a != b:
                        best = INF
                        for pa in range(3):
                            for pb in range(3):
                                if pa != pb and pa != a and pb != b:
                                    best = min(best, dp.get((pa, pb), INF))
                        new_dp[(a, b)] = best + cost[left][a] + cost[right][b]
            dp = new_dp

        return min(dp.values())
