class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        # Build a map from element value to its smallest index
        # For each element value, store the first occurrence index
        elem_map = {}
        for j, e in enumerate(elements):
            if e not in elem_map:
                elem_map[e] = j

        max_group = max(groups)

        # For each possible divisor d, find the smallest index element with value d
        # Then for each group g, find all divisors of g and pick the one with smallest index

        # Precompute: for each value v that appears in elements, 
        # mark all multiples of v up to max_group
        # best[g] = smallest element index that divides g

        best = {}  # group value -> best element index

        for e_val, e_idx in elem_map.items():
            # Mark all multiples of e_val
            multiple = e_val
            while multiple <= max_group:
                if multiple not in best or e_idx < best[multiple]:
                    best[multiple] = e_idx
                multiple += e_val

        result = []
        for g in groups:
            result.append(best.get(g, -1))

        return result
